<?php require __DIR__.'/includes/bootstrap.php'; if(current_user()) redirect('index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$username=trim($_POST['username']??'');$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||strlen($username)<3){$error='Enter valid details. Password must contain at least 8 characters.';}else{try{$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO users(name,email,username,password_hash,role) VALUES(?,?,?,?,'member')");$s->execute([$name,$email,$username,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$code='LIB'.date('ym').str_pad((string)$uid,5,'0',STR_PAD_LEFT);$m=$pdo->prepare("INSERT INTO members(user_id,member_code,name,email,phone,membership_expiry) VALUES(?,?,?,?,?,DATE_ADD(CURDATE(),INTERVAL 1 YEAR))");$m->execute([$uid,$code,$name,$email,$phone]);$pdo->commit();flash('success','Account created. You can now sign in.');redirect('login.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Username or email already exists.';}}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Join Libra</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-body"><div class="auth-card"><div class="auth-logo">L</div><div class="eyebrow">MEMBER REGISTRATION</div><h1>Create your account</h1><p class="muted">Registration creates your library membership. Book issue and return are handled by an administrator.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Username</label><input name="username" minlength="3" required><label>Phone (optional)</label><input name="phone"><label>Password</label><input type="password" name="password" minlength="8" required><button class="btn primary full">Create account</button></form><p class="auth-foot">Already registered? <a href="login.php">Sign in</a></p></div></body></html>
